-- Face Recognition Login System - Database Schema (MySQL/XAMPP)&#10;-- Run: http://localhost/phpmyadmin/ → face_recognition DB → Import&#10;&#10;DROP TABLE IF EXISTS `register`;&#10;&#10;CREATE TABLE `register` (&#10;  `id` int(11) NOT NULL AUTO_INCREMENT,&#10;  `faceid` LONGTEXT NOT NULL COMMENT ''ARRAY OF 128 FLOATS AS JSON'',&#10;  `nama_lengkap` VARCHAR(100) NOT NULL,&#10;  `nama_panggilan` VARCHAR(50) NOT NULL UNIQUE,&#10;  `pin` VARCHAR(255) NOT NULL COMMENT ''password_hash(PIN, PASSWORD_DEFAULT)'',&#10;  PRIMARY KEY (`id`)&#10;) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;&#10;&#10;-- Example INSERT (after face registration via API):&#10;INSERT INTO `register` (`faceid`, `nama_lengkap`, `nama_panggilan`, `pin`) VALUES&#10;('[[0.1,0.2,...128floats...]]', ''John Doe'', ''john'', ''$2y$10$hashedpin'');&#10;&#10;-- API Response Examples:&#10;-- GET /api/get_faces.php → [{''id'':1,''nama_panggilan'':''john'',''faceid'':''[[0.1,...]]''}]&#10;-- POST /api/login.php → {''success'':true,''user'':{''id'':1,''nama_panggilan'':''john'',''faceid'':''[[...]]''}}
